-- Module to track incoming timecode (via serial protocol), process it
-- and send updates for display
-- 
-- Messages received by this module:
--     timecode.update          .. update state of timecode tracking (flywheel etc) cf. timer.tick
--     timecode.raw.reader      .. raw timecode reader packet from protocol
--     timecode.raw.generator   .. raw timecode generator packet from protocol
--
-- Messages generated by this module:
--     timecode.reader          .. display state of supplied reader timecode
--     timecode.generator       .. display state of supplied generator timecode
-------------------------------------------------------------------

print 'remote.timecode'
local message = require 'message'
local timecode = require 'timecode' -- modules.timecode

local TIMECODE_TIMEOUT = 3.0 --1.5

-------------------------------------------------------------------

local TimecodeTracker = class('TimecodeTracker')

function TimecodeTracker:__init(which)
    assert(which == 'reader' or which == 'generator')
    self.tc = timecode.TC()
    self.tc:setUnknown(true)
    self.timer = ElapsedTimer.create()
    self.timeout = 0
    self.which = which
    message.subscribe('timecode.raw.' .. which, function(msg, data)
            self:update(data)
        end)
end

function TimecodeTracker:update(data)
    local elapsed = self.timer:restart()
    if data ~= nil then
--      assert(#data >= 10)
        self.tc:unpack(data)
        self.timeout = TIMECODE_TIMEOUT
    else --if self.tc.run then
        if self.timeout > 0 then
            self.timeout = self.timeout - elapsed
            if self.timeout <= 0 then
                self.timeout = 0
                self.tc:setFreeRun(false)
                self.tc:setUnknown(true)
            end
        end
        if self.tc.run then
            self.tc:advance(elapsed)
        end
    end
    message.send('timecode.' .. self.which, self.tc)
end

-------------------------------------------------------------------

local reader = TimecodeTracker('reader')
local generator = TimecodeTracker('generator')

message.subscribe('timecode.update', function()
        reader:update()
        generator:update()
    end)


